HASH = 'a60458d2180258d47d7f7bef5236b33e86711ac926518ca4545ebf24cdc0b76c'.lower()
rockyou = 'rockyou.txt'

def check_pw(pw, algo):
    if algo == 'sha256':
        h = hashlib.sha256(pw).hexdigest()
    elif algo == 'sha3_256':
        h = hashlib.sha3_256(pw).hexdigest()
    else:
        return False
    return h == HASH

with open(rockyou, 'rb') as f:
