    'whirlpool': lambda data: Whirlpool.new(data).hexdigest(),
    'sha3_256': lambda data: SHA3_256.new(data).hexdigest(),
    'snefru256': lambda data: hashlib_new('snefru256', data).hexdigest(),
}

