import hashlib
import itertools

methods = [
    'md5', 'sha1', 'sha224', 'sha256', 'sha384', 'sha512',
    'sha3_224', 'sha3_256', 'sha3_384', 'sha3_512',
    'blake2b', 'blake2s', 'sm3', 'sha512_224', 'sha512_256',
    'md5-sha1'
]

words = [
    'flag', 'ctf', 'crackme', 'Flag', 'Ctf', 'Crackme', 'FLAG', 'CTF', 'CRACKME',
    'test', 'example', 'password', 'default', 'secret'
]

target = 'a60458d2180258d47d7f7bef5236b33e86711ac926518ca4545ebf24cdc0b76c'

def do_hash(word, method):
    try:
        if method == 'md5-sha1':
            return hashlib.sha1(hashlib.md5(word.encode()).digest()).hexdigest()
        h = hashlib.new(method)
        h.update(word.encode())
        return h.hexdigest()
    except Exception:
        return None

for word in words:
    for method in methods:
        result = do_hash(word, method)
        if result and result.lower() == target:
            print(f'MATCH: {word} using {method}: {result}')
        else:
            print(f'NO: {word} using {method}: {result}')

import hashlib
import binascii

hashval = 'a60458d2180258d47d7f7bef5236b33e86711ac926518ca4545ebf24cdc0b76c'

# Most common 256-bit hashes
def check_common_hashes(candidate):
    # sha256
    if hashlib.sha256(candidate.encode()).hexdigest() == hashval:
        return 'sha256'
    # sha3_256
    if hashlib.sha3_256(candidate.encode()).hexdigest() == hashval:
        return 'sha3_256'
    # sha512/256
    if hashlib.new('sha512_256', candidate.encode()).hexdigest() == hashval:
        return 'sha512_256'
    # whirlpool
    try:
        import hashlib
        import Crypto.Hash.WHIRLPOOL as whirl
        if whirl.new(candidate.encode()).hexdigest() == hashval:
            return 'whirlpool'
    except Exception:
        pass
    # shake_256 (variable len)
    if hashlib.shake_256(candidate.encode()).hexdigest(32) == hashval:
        return 'shake_256'
    # blake2s
    if hashlib.blake2s(candidate.encode()).hexdigest() == hashval:
        return 'blake2s'
    return None

def main():
    # Given there is no wordlist, let's try common passwords and CTF terms.
    candidates = [
        'password', '123456', 'ctf', 'admin', 'letmein', 'welcome', 'flag', 'test', 'crackme',
        'secret', 'example', 'hello', 'root', 'toor', 'guest', 'user', 'default', 'login', 'changeme', 'qwerty',
        'flag{password}', 'flag{ctf}', 'flag{letmein}', 'flag{admin}', 'flag{example}', 'flag{crackme}', 'flag{test}'
    ]
    for c in candidates:
        t = check_common_hashes(c)
        if t:
            print(f'[+] Found! Type: {t}, Plain: {c}')
            return
    print('[!] Not found in default candidates')

if __name__ == '__main__':
    main()

