import hashlib
import itertools
from Crypto.Hash import __all__ as crypto_algos

HASH = 'a60458d2180258d47d7f7bef5236b33e86711ac926518ca4545ebf24cdc0b76c'
CANDIDATES = ['flag', 'ctf', 'crackme', 'score', 'secret', 'root', 'admin', 'password', 'ctfplayer', 'example', 'test', 'challenge', 'hacker', 'letmein'] + [str(i) for i in range(1, 21)]

CASES = lambda w: set([w, w.upper(), w.lower(), w.title()])

matches = []
attempts = 0

def try_hash(algoname, hfunc, word, digest):
    global attempts
    for w in CASES(word):
        attempts += 1
        try:
            h = hfunc()
            h.update(w.encode())
            if h.hexdigest() == digest:
                print(f"[+] FOUND: alg={algoname}, word='{w}'")
                matches.append((algoname, w))
        except Exception as e:
            pass

print("Trying hashlib.algorithms_available, {} entries...".format(len(hashlib.algorithms_available)))
for algo in sorted(hashlib.algorithms_available):
    try:
        hfunc = lambda: hashlib.new(algo)
        for word in CANDIDATES:
            try_hash(algo, hfunc, word, HASH)
    except Exception as e:
        continue

print("Trying Crypto.Hash algorithms...")
for algo in crypto_algos:
    try:
        mod = __import__(f"Crypto.Hash.{algo}", fromlist=['new'])
        hfunc = lambda: mod.new()
        for word in CANDIDATES:
            try_hash(algo.lower(), hfunc, word, HASH)
    except Exception as e:
        continue

print(f"[!] Finished {attempts} attempts, {len(matches)} matches.")
if not matches:
    print("No matches found.")
